import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";

const AdmInfProf = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [professor, setProfessor] = useState(null);

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessores(dados); // Assume que o backend já retorna os dados corretamente
        } else {
          console.error("Erro ao buscar informações do professor");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchProfessor();
  }, [id]);

  if (!professor) {
    return <p>Carregando...</p>;
  }

  return (
    <div className="container mt-4">
      <h1 className="text-primary">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="card mt-3 p-3">
        <h3>{professor.nome}</h3>
        <p>
          <strong>Email:</strong> {professor.email}
        </p>
        <p>
          <strong>Morada:</strong> {professor.morada}
        </p>
        <p>
          <strong>Contacto:</strong> {professor.contacto}
        </p>

        <h5>Cursos que leciona:</h5>
        {professor.cursos && professor.cursos.length > 0 ? (
          <ul>
            {professor.cursos.map((curso, index) => (
              <li key={index}>{curso}</li>
            ))}
          </ul>
        ) : (
          <p>Este professor ainda não tem cursos associados.</p>
        )}

        <button className="btn btn-primary mt-3" onClick={() => navigate(-1)}>
          Voltar
        </button>
      </div>
    </div>
  );
};

export default AdmInfProf;
